try:
    print("VERSION", sys.version.replace("\n", " "))
    print("CPU", __import__("os").cpu_count())
    ce = [1e16, 1.0, -1e16]
    print("counter sum_float", sum(ce), "fsum", math.fsum(ce),
          "accum", list(accumulate(ce, initial=0.0))[-1],
          "reduce", reduce(add, ce, 0.0),
          "complex", sum([complex(x, 0.0) for x in ce]))
    class F(float):
