    print("counter subclass", sum([F(x) for x in ce]), type(sum([F(x) for x in ce])))
    print("sum_float_start0", sum(ce, 0.0))

    def orig(xs, w):
        out = []
        for i in range(len(xs) - w + 1):
            total = 0.0
            for j in range(i, i + w):
                total = total + float(xs[j]) * 1.0
            out.append(total / w)
        return out

    _r = random.Random(7)
    data = [_r.uniform(0, 1) for _ in range(3000)]
    w = 300
    ref = orig(data, w)

    def bits(a):
        return [struct.pack("<d", x) for x in a]

    def m_orig(d, w):
        return orig(d, w)
    def m_sum(d, w):
        dd = list(map(float, d)); return [sum(dd[i:i+w]) / w for i in range(len(dd)-w+1)]
    def m_sum0(d, w):
        dd = list(map(float, d)); return [sum(dd[i:i+w], 0.0) / w for i in range(len(dd)-w+1)]
    def m_fsum(d, w):
        dd = list(map(float, d)); return [math.fsum(dd[i:i+w]) / w for i in range(len(dd)-w+1)]
    def m_reduce(d, w):
        dd = list(map(float, d)); return [reduce(add, dd[i:i+w], 0.0) / w for i in range(len(dd)-w+1)]
    def m_reduce_islice(d, w):
        dd = list(map(float, d)); return [reduce(add, islice(dd, i, i+w), 0.0) / w for i in range(len(dd)-w+1)]
    def m_acc_list(d, w):
        dd = list(map(float, d)); return [list(accumulate(dd[i:i+w], initial=0.0))[-1] / w for i in range(len(dd)-w+1)]
    def m_acc_deque(d, w):
        dd = list(map(float, d)); return [deque(accumulate(dd[i:i+w], initial=0.0), maxlen=1)[0] / w for i in range(len(dd)-w+1)]
    def m_acc_deque_islice(d, w):
        dd = list(map(float, d)); return [deque(accumulate(islice(dd, i, i+w), initial=0.0), maxlen=1)[0] / w for i in range(len(dd)-w+1)]
    def m_complex(d, w):
        dd = [complex(float(x), 0.0) for x in d]; return [sum(dd[i:i+w]).real / w for i in range(len(dd)-w+1)]
    def m_F(d, w):
        dd = [F(float(x)) for x in d]; return [sum(dd[i:i+w]) / w for i in range(len(dd)-w+1)]
    def m_mapstep(d, w):
        dd = list(map(float, d)); m = len(dd)-w+1
        cur = dd[:m]
        for k in range(1, w):
            cur = list(map(add, cur, dd[k:k+m]))
        return [c / w for c in cur]
    def m_sliding(d, w):
        dd = list(map(float, d))
        total = 0.0
        for j in range(w):
            total = total + dd[j]
        out = [total / w]
        for i in range(1, len(dd)-w+1):
            total = total - dd[i-1] + dd[i+w-1]
            out.append(total / w)
        return out
    methods = [
        ("orig", m_orig), ("sum", m_sum), ("sum0", m_sum0), ("fsum", m_fsum),
        ("reduce", m_reduce), ("reduce_islice", m_reduce_islice),
        ("acc_list", m_acc_list), ("acc_deque", m_acc_deque),
        ("acc_deque_islice", m_acc_deque_islice), ("complex", m_complex),
        ("Fsubclass", m_F), ("mapstep", m_mapstep), ("sliding", m_sliding),
    ]
