            # time min of 3
            best = float("inf")
            for _ in range(3):
                t0 = time.perf_counter(); fn(data, w); best = min(best, time.perf_counter()-t0)
            print("METHOD %-18s mism=%d maxdiff=%.3g time=%.5f" % (name, mism, maxdiff, best))
        except Exception as e:
            print("METHOD %-18s ERROR %r" % (name, e))
except Exception as e:
    print("PROBE ERROR", repr(e))
